-- stochastic-processes implementation for RandomStream
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.

local Module = {}
function Module.New(seed)
    local state=math.floor(seed)%2147483647; if state<=0 then state+=2147483646 end
    return {Next=function(self) state=(16807*state)%2147483647; return (state-1)/2147483646 end}
end

return Module
